module Main where

import System.Environment (getArgs)
import Text.Printf (printf)

-- ============================================================
-- Parabola geometry: z(r) = r^2 / (4f)
-- (Kept here for the terminal cut-list report; the HTML viewer
-- reimplements the same math in JS for live in-browser editing.)
-- ============================================================

zOf :: Double -> Double -> Double
zOf f r = r * r / (4 * f)

arcLength :: Double -> Double -> Double
arcLength f r =
  let u = r / (2 * f)
  in (r / 2) * sqrt (1 + u * u) + f * asinh u

darcLength :: Double -> Double -> Double
darcLength f r = sqrt (1 + (r / (2 * f)) ^ (2 :: Int))

radiusForArc :: Double -> Double -> Double
radiusForArc f s = go s 0
  where
    go :: Double -> Int -> Double
    go r n
      | n > 60 = r
      | abs (arcLength f r - s) < 1e-9 * max 1 s = r
      | otherwise =
          let residual = arcLength f r - s
              r'       = max 0 (r - residual / darcLength f r)
          in go r' (n + 1)

data Pt3 = Pt3 { px, py, pz :: Double }

node3D :: Double -> Double -> Double -> Pt3
node3D f r theta = Pt3 (r * cos theta) (r * sin theta) (zOf f r)

dist3 :: Pt3 -> Pt3 -> Double
dist3 a b = sqrt ((px a - px b) ^ (2::Int) + (py a - py b) ^ (2::Int) + (pz a - pz b) ^ (2::Int))

data Dish = Dish { dN :: Int, dF, dS1, dS2, dR1, dR2 :: Double }

mkDish :: Double -> Double -> Int -> Double -> Dish
mkDish diameter fOverD n innerFrac =
  let f  = fOverD * diameter
      r2 = diameter / 2
      s2 = arcLength f r2
      s1 = innerFrac * s2
      r1 = radiusForArc f s1
  in Dish n f s1 s2 r1 r2

spokeAngle :: Dish -> Int -> Double
spokeAngle d k = 2 * pi * fromIntegral k / fromIntegral (dN d)

bisectorAngle :: Dish -> Int -> Double
bisectorAngle d k = spokeAngle d k + pi / fromIntegral (dN d)

innerNode3D, rimAlignedNode3D, rimBisectorNode3D :: Dish -> Int -> Pt3
innerNode3D d k       = node3D (dF d) (dR1 d) (spokeAngle d k)
rimAlignedNode3D d k  = node3D (dF d) (dR2 d) (spokeAngle d k)
rimBisectorNode3D d k = node3D (dF d) (dR2 d) (bisectorAngle d k)

ribALengths :: Dish -> (Double, Double, Double)
ribALengths d = let s1 = dS1 d; s2 = dS2 d - dS1 d in (s1, s2, 2*(s1+s2))

ribBLengths :: Dish -> (Double, Double, Double)
ribBLengths d =
  let i0 = innerNode3D d 0; i1 = innerNode3D d 1; b0 = rimBisectorNode3D d 0
      outerSeg = dist3 b0 i0; innerSeg = dist3 i0 i1
  in (outerSeg, innerSeg, 2*outerSeg + innerSeg)

ribCLength :: Dish -> Double
ribCLength d = dist3 (rimAlignedNode3D d 0) (rimBisectorNode3D d 0)

report :: Dish -> String
report d =
  let (a1,a2,aFull) = ribALengths d
      (b1,b2,bFull) = ribBLengths d
      c             = ribCLength d
  in unlines
    [ printf "Dish: D=%.1fmm  f=%.1fmm  f/D=%.3f  N spokes=%d" (2*dR2 d) (dF d) (dF d/(2*dR2 d)) (dN d)
    , printf "Inner ring: arc=%.1fmm  true radius=%.1fmm" (dS1 d) (dR1 d)
    , printf "Rim ring:   arc=%.1fmm  true radius=%.1fmm" (dS2 d) (dR2 d)
    , ""
    , printf "Rib A (%d pieces): hub-inner=%.1fmm  inner-rim=%.1fmm  full piece=%.1fmm" (dN d `div` 2) a1 a2 aFull
    , printf "Rib B (%d pieces): outer seg=%.1fmm  inner-inner seg=%.1fmm  full piece=%.1fmm" (dN d) b1 b2 bFull
    , printf "Rib C (%d pieces): %.1fmm each" (2 * dN d) c
    ]

-- ============================================================
-- The interactive viewer is now a fixed, self-contained template:
-- it launches at a unit dish (D=2000mm, i.e. 1m radius) and every
-- parameter is then driven live from the in-page input boxes, so
-- no command-line substitution into the HTML is needed any more.
-- ============================================================

htmlTemplate :: String
htmlTemplate = "<!DOCTYPE html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n<title>geodish</title>\n<link href=\"https://fonts.googleapis.com/css2?family=VT323&family=Silkscreen&display=swap\" rel=\"stylesheet\">\n<style>\n  :root { --pxfont: 'VT323', 'Silkscreen', 'Courier New', monospace; }\n  html, body { background:#000; color:#fff; font-family: var(--pxfont); margin:0; padding:0; height:100%; overflow:hidden; }\n  #titleBar { text-align:center; padding:6px 0; background:#000;\n              color:#fff; letter-spacing:6px; font-family: var(--pxfont); font-size:1.8em; }\n  #outer { height: calc(100% - 40px); width:100%; display:flex; align-items:center; justify-content:center; overflow:hidden; }\n  #screen { position:relative; background:#000; }\n  #c { display:block; width:100%; height:100%; image-rendering:pixelated; image-rendering:crisp-edges; cursor:grab; }\n  #c.dragging { cursor:grabbing; }\n\n  .overlay { position:absolute; color:#fff; font-family: var(--pxfont);\n             text-shadow: 1px 1px 0 #000, -1px -1px 0 #000, 1px -1px 0 #000, -1px 1px 0 #000; }\n  #paramsBox { top:0.2em; left:0.2em; }\n  #resultsBox { top:0.2em; right:0.2em; }\n  #legendBox { bottom:0.8em; left:50%; transform:translateX(-50%); width: 94%; }\n  .legendRow { display:flex; align-items:center; height:3.4em; margin-top:0.35em; }\n  .legendRowLabel { width:9ch; flex-shrink:0; font-family: var(--pxfont); font-size:1em; color:#aaa; }\n  .legendRow canvas { flex:1; width:100%; height:100%; display:block;\n                       image-rendering:pixelated; image-rendering:crisp-edges; }\n\n  .consoleLine { display:flex; align-items:baseline; white-space:nowrap; color:#0ff; line-height:0.65; }\n  .padRow { margin-top:0.55em; }\n  .consoleLabel { display:inline-block; width: 15ch; margin-right:0.6em; }\n  .stepChar { color:#0ff; cursor:pointer; padding:0 0.25em; user-select:none; }\n  .stepChar:active { color:#fff; }\n  .consoleVal { background:transparent; border:none; color:#ff0; font-family: var(--pxfont);\n                font-size:1em; text-align:center; width:6ch; outline:none; padding:0; margin:0;\n                line-height:0.65; height:1em; vertical-align:baseline; box-sizing:content-box; }\n  .consoleClick { cursor:pointer; }\n  .consoleClick:active { color:#fff; }\n\n  .resVal2 { color:#ff0; }\n\n  .legendLabel { font-family: var(--pxfont); font-size:1em; color:#aaa; margin-top:0.05em; text-align:center; }\n</style>\n</head>\n<body>\n<div id=\"titleBar\">geodish</div>\n<div id=\"outer\">\n  <div id=\"screen\">\n    <canvas id=\"c\" width=\"640\" height=\"480\"></canvas>\n\n    <div class=\"overlay\" id=\"paramsBox\">\n      <div class=\"consoleLine\"><span class=\"consoleLabel\">stock len (mm)</span><span class=\"stepChar\" data-target=\"pALen\" data-step=\"10\" data-min=\"10\">&lt;</span><input class=\"consoleVal\" id=\"pALen\" value=\"1000\"><span class=\"stepChar\" data-target=\"pALen\" data-step=\"10\" data-min=\"10\" data-dir=\"1\">&gt;</span></div>\n      <div class=\"consoleLine\"><span class=\"consoleLabel\">f/D ratio</span><span class=\"stepChar\" data-target=\"pFD\" data-step=\"0.01\" data-min=\"0.05\" data-max=\"5\">&lt;</span><input class=\"consoleVal\" id=\"pFD\" value=\"0.35\"><span class=\"stepChar\" data-target=\"pFD\" data-step=\"0.01\" data-min=\"0.05\" data-max=\"5\" data-dir=\"1\">&gt;</span></div>\n      <div class=\"consoleLine\"><span class=\"consoleLabel\">spoke count</span><span class=\"stepChar\" data-target=\"pN\" data-step=\"2\" data-min=\"4\" data-max=\"64\" data-int=\"1\">&lt;</span><input class=\"consoleVal\" id=\"pN\" value=\"6\"><span class=\"stepChar\" data-target=\"pN\" data-step=\"2\" data-min=\"4\" data-max=\"64\" data-int=\"1\" data-dir=\"1\">&gt;</span></div>\n      <div class=\"consoleLine\"><span class=\"consoleLabel\">inner ring pos</span><span class=\"stepChar\" data-target=\"pFrac\" data-step=\"0.01\" data-min=\"0.05\" data-max=\"0.95\">&lt;</span><input class=\"consoleVal\" id=\"pFrac\" value=\"0.649\"><span class=\"stepChar\" data-target=\"pFrac\" data-step=\"0.01\" data-min=\"0.05\" data-max=\"0.95\" data-dir=\"1\">&gt;</span><span class=\"consoleClick\" id=\"btnOptimize\" style=\"color:#ff0; margin-left:0.8em;\">optimize</span></div>\n      <div class=\"consoleLine\"><span class=\"consoleLabel\">freq (MHz)</span><span class=\"stepChar\" data-target=\"pFreq\" data-step=\"1\" data-min=\"1\">&lt;</span><input class=\"consoleVal\" id=\"pFreq\" value=\"1420.405\"><span class=\"stepChar\" data-target=\"pFreq\" data-step=\"1\" data-min=\"1\" data-dir=\"1\">&gt;</span></div>\n      <div class=\"consoleLine consoleClick padRow\" id=\"toggleRevY\"></div>\n      <div class=\"consoleLine consoleClick padRow\" id=\"toggleRevZoom\"></div>\n      <div class=\"consoleLine consoleClick padRow\" id=\"toggleIso\"></div>\n    </div>\n\n    <div class=\"overlay\" id=\"resultsBox\">\n      <div class=\"consoleLine padRow\"><span class=\"consoleLabel\">aperture</span><span class=\"resVal2\" id=\"resD\"></span></div>\n      <div class=\"consoleLine padRow\"><span class=\"consoleLabel\">focal len</span><span class=\"resVal2\" id=\"resF\"></span></div>\n      <div class=\"consoleLine padRow\"><span class=\"consoleLabel\">f/D</span><span class=\"resVal2\" id=\"resFD\"></span></div>\n      <div class=\"consoleLine padRow\"><span class=\"consoleLabel\">wavelength</span><span class=\"resVal2\" id=\"resLambda\"></span></div>\n      <div class=\"consoleLine padRow\"><span class=\"consoleLabel\">beam angle</span><span class=\"resVal2\" id=\"resBeam\"></span></div>\n      <div class=\"consoleLine padRow\"><span class=\"consoleLabel\">illum angle</span><span class=\"resVal2\" id=\"resIllum\"></span></div>\n    </div>\n\n    <div class=\"overlay\" id=\"legendBox\">\n      <div class=\"legendRow\"><div class=\"legendRowLabel\" id=\"legendLabelA\"></div><canvas id=\"legendA\" width=\"1600\" height=\"90\"></canvas></div>\n      <div class=\"legendRow\"><div class=\"legendRowLabel\" id=\"legendLabelB\"></div><canvas id=\"legendB\" width=\"1600\" height=\"90\"></canvas></div>\n      <div class=\"legendRow\"><div class=\"legendRowLabel\" id=\"legendLabelC\"></div><canvas id=\"legendC\" width=\"1600\" height=\"90\"></canvas></div>\n    </div>\n  </div>\n</div>\n<script>\n\"use strict\";\n\n// ============ Geometry ============\nfunction zOf(f, r) { return (r*r) / (4*f); }\nfunction arcLength(f, r) {\n  const u = r / (2*f);\n  return (r/2) * Math.sqrt(1 + u*u) + f * Math.asinh(u);\n}\nfunction darcLength(f, r) {\n  const u = r / (2*f);\n  return Math.sqrt(1 + u*u);\n}\nfunction radiusForArc(f, s) {\n  let r = s;\n  for (let n = 0; n < 60; n++) {\n    const residual = arcLength(f, r) - s;\n    if (Math.abs(residual) < 1e-9 * Math.max(1, s)) break;\n    r = Math.max(0, r - residual / darcLength(f, r));\n  }\n  return r;\n}\nfunction node3D(f, r, theta) { return [r*Math.cos(theta), r*Math.sin(theta), zOf(f, r)]; }\nfunction dist3(a, b) {\n  const dx = a[0]-b[0], dy = a[1]-b[1], dz = a[2]-b[2];\n  return Math.sqrt(dx*dx + dy*dy + dz*dz);\n}\nfunction mid3(a, b) { return [(a[0]+b[0])/2, (a[1]+b[1])/2, (a[2]+b[2])/2]; }\nfunction buildDish(diameter, fOverD, N, innerFrac) {\n  const f = fOverD * diameter;\n  const r2 = diameter / 2;\n  const s2 = arcLength(f, r2);\n  const s1 = innerFrac * s2;\n  const r1 = radiusForArc(f, s1);\n  return {N, f, s1, s2, r1, r2, diameter, fOverD};\n}\nfunction diameterFromALength(aTotalLen, fOverD) {\n  const Dref = 2;\n  const fRef = fOverD * Dref;\n  const s2Ref = arcLength(fRef, 1);\n  const s2Target = aTotalLen / 2;\n  return Dref * (s2Target / s2Ref);\n}\nfunction spokeAngle(d, k) { return 2*Math.PI*k/d.N; }\nfunction bisectorAngle(d, k) { return spokeAngle(d,k) + Math.PI/d.N; }\nfunction innerNode(d,k){ return node3D(d.f, d.r1, spokeAngle(d,k)); }\nfunction rimAligned(d,k){ return node3D(d.f, d.r2, spokeAngle(d,k)); }\nfunction rimBisector(d,k){ return node3D(d.f, d.r2, bisectorAngle(d,k)); }\nfunction hubNode(){ return [0,0,0]; }\n\n// ============ Colors ============\nconst COL_A_INNER = \"#fff\";\nconst COL_A_OUTER = \"#aaa\";\nconst COL_B_RING  = \"#0ff\";\nconst COL_B_LEG   = \"#f0f\";\nconst COL_C       = \"#ff0\";\nconst CYCLE = [\"#fff\", \"#0ff\", \"#ff0\", \"#f0f\"];\nfunction cyclingColor(t) { return CYCLE[Math.floor(t / 75) % 4]; }\nfunction cyclingColorSlow(t) { return CYCLE[Math.floor(t / 150) % 4]; }\n\n// ============ Camera ============\nlet azimuth = 0.9;\nlet elevation = 0.55;\nlet reverseY = false;\nlet reverseZoom = false;\nlet zoom = 1.8;\nlet isoMode = false;\nlet uiScale = 1; // set by resizeCanvas(); the one shared scale factor for all text and legend canvases\nconst BASE_PX = 13; // the single font-size (in \"unscaled\" pixels) shared by every piece of on-screen text\n\nfunction project(pt, w, h, dist) {\n  let [x,y,z] = pt;\n\n  const ca = Math.cos(azimuth), sa = Math.sin(azimuth);\n  const ce = Math.cos(elevation), se = Math.sin(elevation);\n\n  const x1 = x*ca - y*sa;\n  const y1 = x*sa + y*ca;\n  const z1 = z;\n\n  const y2 = y1*ce - z1*se;\n  const z2 = y1*se + z1*ce;\n\n  const scale = zoom * 0.42 * Math.min(w,h) / dist;\n  const persp = isoMode ? 1 : (1 / (1 + y2 / (dist*2.2)));\n  const sx = w/2 + x1 * scale * persp;\n  const sy = h/2 - z2 * scale * persp;\n  return [sx, sy, y2];\n}\n\n// ============ Rendering ============\nconst canvas = document.getElementById('c');\nconst ctx = canvas.getContext('2d');\n\nlet segments = [];\n\nfunction line(p1, p2, color, width, group) {\n  ctx.strokeStyle = color;\n  ctx.lineWidth = width || 1;\n  ctx.beginPath();\n  ctx.moveTo(p1[0], p1[1]);\n  ctx.lineTo(p2[0], p2[1]);\n  ctx.stroke();\n  if (group) segments.push({x1:p1[0], y1:p1[1], x2:p2[0], y2:p2[1], group});\n}\nfunction dot(p, color, r) {\n  ctx.fillStyle = color;\n  ctx.beginPath();\n  ctx.arc(p[0], p[1], r||2, 0, 2*Math.PI);\n  ctx.fill();\n}\nfunction text(p, str, color) {\n  const fpx = BASE_PX;\n  ctx.font = fpx + \"px 'VT323', 'Silkscreen', monospace\";\n  const wpx = ctx.measureText(str).width;\n  ctx.fillStyle = \"rgba(0,0,0,0.75)\";\n  ctx.fillRect(p[0]-wpx/2-2, p[1]-fpx*0.9, wpx+4, fpx*1.05);\n  ctx.fillStyle = color;\n  ctx.textAlign = \"center\";\n  ctx.fillText(str, p[0], p[1]-1);\n  ctx.textAlign = \"left\";\n}\n\nlet hoveredGroup = null;\n\nfunction drawLine(p1screen, p2screen, baseColor, baseWidth, group, time) {\n  const isHi = hoveredGroup !== null && group === hoveredGroup;\n  const col = isHi ? cyclingColor(time) : baseColor;\n  const w   = baseWidth;\n  line(p1screen, p2screen, col, w, group);\n}\n\nfunction val(id, fallback) {\n  const v = parseFloat(document.getElementById(id).value);\n  return isFinite(v) ? v : fallback;\n}\n\nfunction draw(time) {\n  if (typeof time !== 'number') time = Date.now();\n  const w = canvas.width, h = canvas.height;\n  ctx.fillStyle = \"#000\";\n  ctx.fillRect(0,0,w,h);\n  segments = [];\n\n  const ALEN = val('pALen', 1000);\n  const FD = val('pFD', 0.35);\n  const N = Math.max(4, Math.round(val('pN', 6)));\n  const FRAC = Math.min(0.95, Math.max(0.05, val('pFrac', 0.649)));\n  const FREQ = Math.max(1, val('pFreq', 1420.405));\n  document.getElementById('toggleRevY').textContent = (reverseY ? \"[x] \" : \"[ ] \") + \"reverse y-axis\";\n  document.getElementById('toggleRevZoom').textContent = (reverseZoom ? \"[x] \" : \"[ ] \") + \"reverse zoom\";\n  document.getElementById('toggleIso').textContent = (isoMode ? \"[x] \" : \"[ ] \") + \"isometric\";\n\n  const D = diameterFromALength(ALEN, FD);\n  const d = buildDish(D, FD, N, FRAC);\n  const camDist = D * 2.0;\n  const P = (pt) => project(pt, w, h, camDist);\n\n  const axisLen = D * 0.75;\n  const Xp = P([axisLen,0,0]), Xn = P([-axisLen,0,0]);\n  const Yp = P([0,axisLen,0]), Yn = P([0,-axisLen,0]);\n  const Zp = P([0,0,axisLen]), Zn = P([0,0,-axisLen*0.15]);\n\n  line(Xn, Xp, \"#0ff\", 1);\n  line(Yn, Yp, \"#f0f\", 1);\n  line(Zn, Zp, \"#ff0\", 1);\n  text(Xp, \"x\", \"#0ff\");\n  text(Yp, \"y\", \"#f0f\");\n  text(Zp, \"z\", \"#ff0\");\n\n  const nTicks = 5;\n  ctx.fillStyle = \"#fff\";\n  for (let i=1;i<=nTicks;i++) {\n    const t = (D/2) * i / nTicks;\n    for (const axisVec of [[t,0,0],[0,t,0],[0,0,t]]) {\n      const p = P(axisVec);\n      ctx.fillRect(p[0]-1, p[1]-1, 2, 2);\n    }\n  }\n\n  const apPts = [];\n  for (let k=0;k<=64;k++) {\n    const th = 2*Math.PI*k/64;\n    apPts.push(P([d.r2*Math.cos(th), d.r2*Math.sin(th), 0]));\n  }\n  ctx.strokeStyle = \"#666\";\n  ctx.lineWidth = 1;\n  ctx.setLineDash([4,3]);\n  ctx.beginPath();\n  apPts.forEach((p,i)=> i===0 ? ctx.moveTo(p[0],p[1]) : ctx.lineTo(p[0],p[1]));\n  ctx.stroke();\n  ctx.setLineDash([]);\n  text(P([d.r2,0,0]), \"D=\" + D.toFixed(0) + \"mm\", \"#ccc\");\n  text(P([0,d.r2,0]), \"f/D=\" + (d.f/D).toFixed(3), \"#ccc\");\n\n  // psi = half-angle from focus to rim (standard parabolic-feed formula),\n  // computed once here and reused for both the focal-point label and the\n  // cone drawn below, plus the results-panel readout further down.\n  const psi = 2 * Math.atan(1 / (4 * (d.f / D)));\n  const illumFullDeg = 2 * psi * 180 / Math.PI;\n\n  const focalScreen = P([0,0,d.f]);\n  const focalCol = cyclingColorSlow(time); // deliberately the slower rate, to stay visually distinct from hover highlights\n  dot(focalScreen, focalCol, 4);\n  text([focalScreen[0], focalScreen[1]-8], \"f=\" + d.f.toFixed(0) + \"mm  \" + illumFullDeg.toFixed(0) + \"deg\", focalCol);\n\n  // ---- illumination cone: a short visual cue only (not drawn all the\n  // way to the rim, which would clutter the view) -- same half-angle\n  // psi as above, just truncated to ~12% of the focus-to-rim distance.\n  {\n    const focus3 = [0, 0, d.f];\n    const fullLen = dist3(focus3, [d.r2, 0, zOf(d.f, d.r2)]); // true focus-to-rim distance\n    const coneLen = 0.12 * fullLen;\n    const cCol = cyclingColorSlow(time);\n    const nCone = 16;\n    const conePts = [];\n    for (let i = 0; i < nCone; i++) {\n      const phi = 2 * Math.PI * i / nCone;\n      const dir = [Math.sin(psi)*Math.cos(phi), Math.sin(psi)*Math.sin(phi), -Math.cos(psi)];\n      const pt3 = [focus3[0]+coneLen*dir[0], focus3[1]+coneLen*dir[1], focus3[2]+coneLen*dir[2]];\n      conePts.push(P(pt3));\n    }\n    // spokes from focus\n    for (let i = 0; i < nCone; i += 2) {\n      line(focalScreen, conePts[i], cCol, 1);\n    }\n    // base circle\n    for (let i = 0; i < nCone; i++) {\n      line(conePts[i], conePts[(i+1)%nCone], cCol, 1);\n    }\n\n  }\n\n  const hub3 = P(hubNode());\n  const halfN = N / 2;\n\n  for (let k=0;k<N;k++) {\n    const inn = P(innerNode(d,k));\n    const rim = P(rimAligned(d,k));\n    const group = \"A_\" + (k % halfN);\n    drawLine(hub3, inn, COL_A_INNER, 2.5, group, time);\n    drawLine(inn, rim, COL_A_OUTER, 2.5, group, time);\n    dot(inn, COL_A_INNER, 2);\n    dot(rim, COL_A_OUTER, 2);\n  }\n  dot(hub3, COL_A_INNER, 3);\n\n  for (let k=0;k<N;k++) {\n    const bi  = P(rimBisector(d,k));\n    const in0 = P(innerNode(d,k));\n    const in1 = P(innerNode(d,(k+1)%N));\n    const groupLeg1 = \"B_\" + ((k - 1 + N) % N);\n    const groupRing = \"B_\" + k;\n    const groupLeg2 = \"B_\" + ((k + 1) % N);\n    drawLine(bi, in0, COL_B_LEG, 1.8, groupLeg1, time);\n    drawLine(bi, in1, COL_B_LEG, 1.8, groupLeg2, time);\n    drawLine(in0, in1, COL_B_RING, 1.8, groupRing, time);\n  }\n\n  for (let k=0;k<N;k++) {\n    const ra  = P(rimAligned(d,k));\n    const rb  = P(rimBisector(d,k));\n    const ra2 = P(rimAligned(d,(k+1)%N));\n    drawLine(ra, rb, COL_C, 1.5, \"C_\" + k + \"_1\", time);\n    drawLine(rb, ra2, COL_C, 1.5, \"C_\" + k + \"_2\", time);\n    dot(rb, COL_C, 2);\n  }\n\n  const aLen1 = d.s1;\n  const aLen2 = d.s2 - d.s1;\n  const bOuter = dist3(rimBisector(d,0), innerNode(d,0));\n  const bInner = dist3(innerNode(d,0), innerNode(d,1));\n  const cLen  = dist3(rimAligned(d,0), rimBisector(d,0));\n\n  text(P(mid3(hubNode(), innerNode(d,0))),        aLen1.toFixed(0)+\"mm\",  COL_A_INNER);\n  text(P(mid3(innerNode(d,0), rimAligned(d,0))),  aLen2.toFixed(0)+\"mm\",  COL_A_OUTER);\n  text(P(mid3(innerNode(d,0), innerNode(d,1))),   bInner.toFixed(0)+\"mm\", COL_B_RING);\n  text(P(mid3(rimBisector(d,0), innerNode(d,0))), bOuter.toFixed(0)+\"mm\", COL_B_LEG);\n  text(P(mid3(rimAligned(d,0), rimBisector(d,0))),cLen.toFixed(0)+\"mm\",   COL_C);\n\n  // ---- results overlay ----\n  const lambdaMM = 299792.458 / FREQ;\n  const beamDeg = 70 * lambdaMM / D;\n  document.getElementById('resD').textContent = D.toFixed(1) + \"mm\";\n  document.getElementById('resF').textContent = d.f.toFixed(1) + \"mm\";\n  document.getElementById('resFD').textContent = (d.f/D).toFixed(3);\n  document.getElementById('resLambda').textContent = lambdaMM.toFixed(1) + \"mm @ \" + FREQ.toFixed(1) + \"MHz\";\n  document.getElementById('resBeam').textContent = \"~\" + beamDeg.toFixed(1) + \"deg\";\n  document.getElementById('resIllum').textContent = illumFullDeg.toFixed(1) + \"deg\";\n\n  drawLegends(d, aLen1, aLen2, bOuter, bInner, cLen, time);\n}\n\nfunction drawSchematic(canvasId, segLens, segColors, scalePxPerMm, time, isHoveredFn) {\n  const cv = document.getElementById(canvasId);\n  const c2 = cv.getContext('2d');\n  const W = cv.width, H = cv.height;\n  c2.fillStyle = \"#000\";\n  c2.fillRect(0,0,W,H);\n  const baseLineW = 8;\n  const tickHalf = 1.5 * baseLineW; // total tick height = 3x the line width\n  const fontPx = 22;\n  const marginL = 16;\n  const yMid = tickHalf + fontPx + 8; // headroom above for the label so it never clips\n  let x = marginL;\n  const xs = [x];\n  const hoveredTickIdx = new Set();\n  for (const len of segLens) {\n    const nx = x + len * scalePxPerMm;\n    const hi = isHoveredFn && isHoveredFn(xs.length-1);\n    if (hi) { hoveredTickIdx.add(xs.length-1); hoveredTickIdx.add(xs.length); }\n    c2.strokeStyle = hi ? cyclingColor(time) : segColors[xs.length-1];\n    c2.lineWidth = baseLineW;\n    c2.beginPath();\n    c2.moveTo(x, yMid);\n    c2.lineTo(nx, yMid);\n    c2.stroke();\n    c2.fillStyle = \"#ccc\";\n    c2.font = fontPx + \"px 'VT323', 'Silkscreen', monospace\";\n    c2.textAlign = \"center\";\n    c2.textBaseline = \"bottom\";\n    c2.fillText(len.toFixed(0), (x+nx)/2, yMid - tickHalf - 4);\n    x = nx;\n    xs.push(x);\n  }\n  c2.textAlign = \"left\";\n  c2.textBaseline = \"alphabetic\";\n  c2.lineWidth = 3;\n  xs.forEach((hx, i) => {\n    // Hash marks bounding a currently-hovered/highlighted member are drawn\n    // yellow instead of plain white, to visually tie the tick marks to the\n    // same selection as the highlighted line and legend row.\n    c2.strokeStyle = hoveredTickIdx.has(i) ? \"#ff0\" : \"#fff\";\n    c2.beginPath();\n    c2.moveTo(hx, yMid - tickHalf);\n    c2.lineTo(hx, yMid + tickHalf);\n    c2.stroke();\n  });\n}\n\nfunction drawLegends(d, aLen1, aLen2, bOuter, bInner, cLen, time) {\n  const totalA = 2*(aLen1+aLen2);\n  const totalB = 2*bOuter + bInner;\n  const totalC = cLen;\n  const maxTotal = Math.max(totalA, totalB, totalC);\n  const usableW = 1600 - 40;\n  const scale = usableW / maxTotal;\n\n  const hoverA = hoveredGroup !== null && hoveredGroup.startsWith(\"A_\");\n  const hoverB = hoveredGroup !== null && hoveredGroup.startsWith(\"B_\");\n  const hoverC = hoveredGroup !== null && hoveredGroup.startsWith(\"C_\");\n\n  drawSchematic(\"legendA\", [aLen2, aLen1, aLen1, aLen2],\n    [COL_A_OUTER, COL_A_INNER, COL_A_INNER, COL_A_OUTER], scale, time, () => hoverA);\n  drawSchematic(\"legendB\", [bOuter, bInner, bOuter],\n    [COL_B_LEG, COL_B_RING, COL_B_LEG], scale, time, () => hoverB);\n  drawSchematic(\"legendC\", [cLen],\n    [COL_C], scale, time, () => hoverC);\n\n  document.getElementById('legendLabelA').textContent = \"rib a (x\" + (d.N/2) + \")\";\n  document.getElementById('legendLabelB').textContent = \"rib b (x\" + d.N + \")\";\n  document.getElementById('legendLabelC').textContent = \"rib c (x\" + (2*d.N) + \")\";\n}\n\n// ============ Aspect-ratio-preserving screen sizing ============\nfunction resizeCanvas() {\n  const outer = document.getElementById('outer');\n  const screen = document.getElementById('screen');\n  const availW = outer.clientWidth, availH = outer.clientHeight;\n  const targetRatio = canvas.width / canvas.height;\n  let cw, ch;\n  if (availW / availH > targetRatio) { ch = availH; cw = ch * targetRatio; }\n  else { cw = availW; ch = cw / targetRatio; }\n  screen.style.width = cw + \"px\";\n  screen.style.height = ch + \"px\";\n  uiScale = cw / 640;\n  screen.style.fontSize = (uiScale * BASE_PX) + \"px\";\n}\n\n// ============ Mouse orbit + wheel zoom + hover hit-testing ============\nlet dragging = false, lastX=0, lastY=0;\ncanvas.addEventListener('mousedown', (e)=>{ dragging=true; lastX=e.clientX; lastY=e.clientY; canvas.classList.add('dragging'); });\nwindow.addEventListener('mouseup', ()=>{ dragging=false; canvas.classList.remove('dragging'); });\n\nfunction distToSegment(px, py, x1, y1, x2, y2) {\n  const dx = x2-x1, dy = y2-y1;\n  const lenSq = dx*dx + dy*dy;\n  let t = lenSq === 0 ? 0 : ((px-x1)*dx + (py-y1)*dy) / lenSq;\n  t = Math.max(0, Math.min(1, t));\n  const cx = x1 + t*dx, cy = y1 + t*dy;\n  return Math.hypot(px-cx, py-cy);\n}\n\nwindow.addEventListener('mousemove', (e)=>{\n  if (dragging) {\n    const dx = e.clientX - lastX, dy = e.clientY - lastY;\n    lastX = e.clientX; lastY = e.clientY;\n    azimuth += dx * 0.01;\n    elevation = Math.max(-1.5, Math.min(1.5, elevation + dy * 0.01 * (reverseY ? -1 : 1)));\n    return;\n  }\n  const rect = canvas.getBoundingClientRect();\n  if (rect.width === 0 || rect.height === 0) return;\n  const scaleX = canvas.width / rect.width, scaleY = canvas.height / rect.height;\n  const mx = (e.clientX - rect.left) * scaleX;\n  const my = (e.clientY - rect.top) * scaleY;\n  let best = null, bestDist = 8;\n  for (const s of segments) {\n    const dpx = distToSegment(mx, my, s.x1, s.y1, s.x2, s.y2);\n    if (dpx < bestDist) { bestDist = dpx; best = s.group; }\n  }\n  hoveredGroup = best;\n});\n\ncanvas.addEventListener('wheel', (e)=>{\n  e.preventDefault();\n  const dir = (reverseZoom ? -1 : 1) * (e.deltaY > 0 ? -1 : 1);\n  zoom = Math.max(0.1, Math.min(20, zoom * (1 + dir * 0.1)));\n}, { passive:false });\n\ndocument.querySelectorAll('input').forEach(el => el.addEventListener('input', draw));\nwindow.addEventListener('resize', () => { resizeCanvas(); });\n\ndocument.getElementById('toggleRevY').addEventListener('click', () => { reverseY = !reverseY; });\ndocument.getElementById('toggleRevZoom').addEventListener('click', () => { reverseZoom = !reverseZoom; });\ndocument.getElementById('toggleIso').addEventListener('click', () => { isoMode = !isoMode; });\n\n// ============ Step controls (< / > characters, console-line style) ============\ndocument.querySelectorAll('.stepChar').forEach(el => {\n  el.addEventListener('click', () => {\n    const targetId = el.dataset.target;\n    const step = parseFloat(el.dataset.step);\n    const dir = el.dataset.dir === \"1\" ? 1 : -1;\n    const min = el.dataset.min !== undefined ? parseFloat(el.dataset.min) : undefined;\n    const max = el.dataset.max !== undefined ? parseFloat(el.dataset.max) : undefined;\n    const isInt = el.dataset.int === \"1\";\n    const inp = document.getElementById(targetId);\n    let v = parseFloat(inp.value);\n    if (!isFinite(v)) v = 0;\n    v += dir * step;\n    if (min !== undefined) v = Math.max(min, v);\n    if (max !== undefined) v = Math.min(max, v);\n    inp.value = isInt ? Math.round(v).toString() : parseFloat(v.toFixed(6)).toString();\n    draw();\n  });\n});\n\n// ============ \"Optimize\" button ============\nfunction bLengthDiff(D, fOverD, N, frac) {\n  const dd = buildDish(D, fOverD, N, frac);\n  const bOuter = dist3(rimBisector(dd,0), innerNode(dd,0));\n  const bInner = dist3(innerNode(dd,0), innerNode(dd,1));\n  return bOuter - bInner;\n}\nfunction optimizeFrac(D, fOverD, N) {\n  const lo0 = 0.05, hi0 = 0.95, steps = 80;\n  let prevF = lo0, prevG = bLengthDiff(D, fOverD, N, prevF);\n  let braLo = null, braHi = null;\n  for (let i = 1; i <= steps; i++) {\n    const f = lo0 + (hi0 - lo0) * i / steps;\n    const g = bLengthDiff(D, fOverD, N, f);\n    if (Math.sign(g) !== Math.sign(prevG) || g === 0) { braLo = prevF; braHi = f; break; }\n    prevF = f; prevG = g;\n  }\n  if (braLo === null) return null;\n  let lo = braLo, hi = braHi;\n  const glo0 = bLengthDiff(D, fOverD, N, lo);\n  for (let i = 0; i < 60; i++) {\n    const mid = (lo + hi) / 2;\n    const gmid = bLengthDiff(D, fOverD, N, mid);\n    if (Math.sign(gmid) === Math.sign(glo0)) lo = mid; else hi = mid;\n  }\n  return (lo + hi) / 2;\n}\ndocument.getElementById('btnOptimize').addEventListener('click', () => {\n  const ALEN = val('pALen', 1000);\n  const FD = val('pFD', 0.35);\n  const N = Math.max(4, Math.round(val('pN', 6)));\n  const D = diameterFromALength(ALEN, FD);\n  const result = optimizeFrac(D, FD, N);\n  if (result !== null) {\n    document.getElementById('pFrac').value = result.toFixed(6);\n  }\n});\n\n// ============ Animation loop ============\nfunction loop(t) {\n  draw(t);\n  if (typeof requestAnimationFrame === 'function') requestAnimationFrame(loop);\n}\nresizeCanvas();\nif (typeof requestAnimationFrame === 'function') requestAnimationFrame(loop);\nelse draw();\n</script>\n</body>\n</html>\n"


main :: IO ()
main = do
  args <- getArgs
  case args of
    (diamStr : fdStr : rest) -> do
      let diameter = read diamStr :: Double
          fOverD   = read fdStr :: Double
          n        = case rest of (nStr:_) -> read nStr :: Int; _ -> 6
          innerFr  = case rest of (_:fracStr:_) -> read fracStr :: Double; _ -> 0.649
          outPath  = case rest of (_:_:pathStr:_) -> pathStr; _ -> "geodish.html"
          dish     = mkDish diameter fOverD n innerFr
      putStr (report dish)
      writeFile outPath htmlTemplate
      putStrLn ("\n(Cut-list above is for the numbers you gave; the viewer itself always")
      putStrLn "opens at a unit dish -- use the on-page inputs to dial in these values.)"
      putStrLn ("\nInteractive viewer written to " ++ outPath ++ " -- open it in a browser.")
    [] -> do
      writeFile "geodish.html" htmlTemplate
      putStrLn "Interactive viewer written to geodish.html  open it in a browser."
    _ -> putStrLn "usage: geodish [<diameter_mm> <f/D> [numSpokes=6] [innerRingArcFraction=0.649] [geodish.html]]"
